  const auto& completed=world.national_campaigns->seasons.at(season);check(completed.winner.valid(),"completed tournament lacks its Source winner");const auto facts=national_final_facts(completed);check(facts.winner==completed.winner&&facts.runner_up==completed.runner_up,"pure Source final facts disagree");auto tampered=world;auto& corrupted=tampered.national_campaigns->seasons.at(season);auto& final=*std::find_if(corrupted.stages.begin(),corrupted.stages.end(),[&](const auto& s){return s.rules.entry==corrupted.active_entry;});const auto wrong=*std::find_if(corrupted.entrants.begin(),corrupted.entrants.end(),[&](auto id){return id!=corrupted.winner;});corrupted.winner=wrong;final.winner=wrong;rejects([&]{(void)national_final_facts(corrupted);});if(season%2==0){const auto rejected=tampered;const auto gs=game;const auto ws=random;rejects([&]{prepare_national_campaign(tampered,source,season+1,game,random,primary);});check(tampered==rejected&&game.seed()==gs.seed()&&game.calls()==gs.calls()&&random.seed()==ws.seed()&&random.calls()==ws.calls(),"tampered prior awards consumed next draw RNG or published a field");}if(season%4==3)check(world.national_campaigns->honours.front()==completed.places,"World-Cup Source podium/honours were not retained");
